ation de compte ou de personnage n’est incluse. Si désactivé, le QR contient uniquement X, Y et Z.50:Les données QR avancées ne sont pas disponibles.7:Couleur46:Modifie la couleur du texte GPS et du code QR.9:X : <<1>>9:Y : <<1>>9:Z : <<1>>20:Format d’affichage146:Choisit d’afficher vos coordonnées globales actuelles sous forme de code QR, de texte brut ou de valeurs CSV. Les codes QR nécessitent LibQRC.14:Activer le GPS66:Affiche vos coordonnées globales LibGPS actuelles pendant le jeu.70:Configure l’affichage de vos coordonnées globales LibGPS actuelles.6:Police16:Taille de police55:Modifie la taille du texte GPS et des coordonnées CSV.70:Modifie la police utilisée pour le texte GPS et les coordonnées CSV.11:Valeurs CSV7:Code QR10:Texte brut20:Position horizontale69:Déplace l’affichage GPS vers la gauche ou la droite de l’écran.31:Position actuelle indisponible.3:GPS8:Opacité42:Modifie l’opacité de l’affichage GPS.11:Horizontale11:Orientation111:Choisit si les coordonnées en texte brut apparaissent sur une ligne horizontale ou dans une colonne verticale.9:Verticale33:X : <<1>>   Y : <<2>>   Z : <<3>>40:Le code QR n’a pas pu être généré.17:Taille du code QR68:Modifie la largeur et la hauteur de l’affichage carré du code QR.7:Code QR5:Texte29:Afficher dans les paramètres138:Maintient l’affichage GPS visible sur cette page de paramètres afin de prévisualiser les modifications lorsque le GPS est désactivé.58:Indisponible, car LibGPS n’est pas installé ou activé.112:Les codes QR nécessitent LibQRC. Installez-le et activez-le, ou sélectionnez le texte brut ou les valeurs CSV.26:Fréquence de mise à jour171:Définit la fréquence de vérification des coordonnées GPS. Des valeurs plus faibles accélèrent les mises à jour et peuvent utiliser davantage de temps de traitement.7:%.0f ms18:Position verticale64:Déplace l’affichage GPS vers le haut ou le bas de l’écran.6:Alarme15:Son de l'alarme92:Sélectionne le son intégré du jeu joué lorsqu'une annonce correspond à un mot d'alarme.