    de = "15:Geladen v<<1>>.8:ERWORBEN5:AKTIV4:Nach6:Analog4:Auto10:Verfügbar3:Vor5:Unten10:Unten-oben10:Stornieren14:Herausforderer9:Charakter13:Charaktername5:Kreis13:Abgeschlossen11:Bestätigen15:Fortgeschritten7:Einfach7:Termine4:Voll13:<<1>> - <<2>>7:Diamant7:Digital13:Zurückweisen6:Gleich5:Extra9:Freihafen11:Ausrüstung13:Gruppenrahmen9:Minikarte9:Reittiere14:Bereitstellung5:Antik12:Gamepad fett13:Gamepad-Licht14:Gamepad mittel15:Handschriftlich13:Tastatur fett15:Tastatur mittel9:Allgemein4:Gold12:Harter Modus18:Harter Modus <<1>>10:Horizontal14:In Bearbeitung10:Artikelset7:Artikel7:BEKANNT5:Links8:Gesperrt8:%.0f min9:<<1>> min5:FEHLT4:Nein8:Kein Tod5:Keine6:Normal14:NICHT ERWORBEN16:Nicht verfügbar19:Nicht abgeschlossen16:Nicht festgelegt18:Nicht unterstützt6:Nichts6:Nummer3:Aus11:Prozentsatz10:Spieler-ID8:Vorschau7:Relativ6:Rechts13:Rechter Stock6:Suchen8:%.0f Sek11:AUSGEWÄHLT12:Aktiv setzen15:<<1>> angezeigt15:Geschwindigkeit7:Quadrat12:Unterstützt6:Spitze10:Oben-Unten6:Reisen8:Trifecta9:UNBEKANNT9:Unbekannt14:Freigeschaltet9:Verwenden11:Benutzer-ID11:NQOL v<<1>>8:Vertikal7:Veteran2:Ja35:Exakter Text, durch Kommas getrennt188:Sie haben NQOL erfolgreich installiert. Die Standardeinstellungen haben keinen Einfluss auf das Spiel. Sie müssen die benötigten NQOL-Funktionen manuell über Optionen > NQOL aktivieren.19:Willkommen bei NQOL113:Das Ändern der NQOL-Sprache erfordert ein Neuladen der Benutzeroberfläche. Benutzeroberfläche jetzt neu laden?16:Sprache ändern?82:Goldgewinne, Gold pro Minute und Chartverlauf der aktuellen Sitzung zurücksetzen?88:XP-Gewinne der aktuellen Sitzung, XP-pro-Minute-Raten und Diagrammverlauf zurücksetzen?12:Was ist neu?20:Was ist neu in NQOL?8:Auto-Eye120:Verwendet automatisch das Auge des Antiquars, wenn es in einer aktiven antiken Ausgrabungsstätte verwendet werden kann.13:Alle anzeigen17:Fehlende anzeigen32:Filter „Alle aktiven Leads“.130:Fügt „Vermisst anzeigen“ zu „Alle aktiven Leads“ hinzu und zeigt nur Antiquitäten ohne freigeschalteten Kodexeintrag an.24:Spur bereits ausgegraben23:Händler-Spurenanzeigen166:Zeigt eine Sanduhr für derzeit vorhandene Spuren und ein grünes Häkchen für bereits ausgegrabene Spuren. Treffen beide Zustände zu, wechseln sich die Symbole ab.22:Spur derzeit im Besitz20:Hintergrundopazität76:Passt an, wie undurchsichtig der Hintergrund des Buffs/Debuffs-Trackers ist.9:Aktiviert65:Lädt und zeigt den Buffs/Debuffs-Tracker während des Spiels an.10:Schriftart14:Schriftgröße44:Ändert die Größe der Buffs/Debuffs-Namen.71:Wählt die Schriftart aus, die für Buffs/Debuffs-Namen verwendet wird.20:Horizontale Position79:Verschiebt die Buffs/Debuffs-Tabelle auf dem Bildschirm nach links oder rechts.12:Hauptmonitor63:Zeigt die Spalte „Haupteffekt“ im Buffs/Debuffs-Tracker an.15:Kleiner Monitor68:Zeigt die Spalte „Kleinerer Effekt“ im Buffs/Debuffs-Tracker an.96:Ermöglicht dem Tracker, <<1>> Buff-Zeilen anzuzeigen, wenn „Ausgewählter Track“ aktiv ist.96:Ermöglicht dem Tracker, <<1>> Debuff-Zeilen anzuzeigen, wenn „Ausgewählte Spur“ aktiv ist.29:In den Einstellungen anzeigen120:Die Buffs/Debuffs-Tabelle bleibt hier sichtbar, sodass Platzierungsänderungen in der Vorschau angezeigt werden können.6:Stapel109:Steuert, ob Buffs/Debuffs-Zeilen vom oberen Rand nach unten oder vom unteren Rand nach oben erweitert werden.19:Verfolgen Sie alles21:Verfolgen, wenn aktiv17:Titel ausgewählt5:Modus104:Steuert, ob der Tracker alle überwachten Effekte, nur aktive Effekte oder ausgewählte Effekte anzeigt.26:Verwenden Sie Spielsymbole141:Zeigt ESO-Effektsymbole an. Wenn diese Option deaktiviert ist, verwenden Haupteffekte rote Markierungen und Nebeneffekte grüne Markierungen.18:Vertikale Position77:Verschiebt die Buffs/Debuffs-Tabelle auf dem Bildschirm nach oben oder unten.13:Zoom im Kampf116:Legt den Zoom der Drittpersonenkamera im Kampf fest. Dies überschreibt die Werte für zu Fuß und auf dem Reittier.9:Aktiviert102:Wendet automatisch den konfigurierten Zoom der Drittpersonenkamera für den aktuellen Spielzustand an.85:Konfiguriert automatische Zoomstufen der Drittpersonenkamera für jeden Spielzustand.17:Zoom auf Reittier83:Legt den Zoom der Drittpersonenkamera auf dem Reittier außerhalb des Kampfes fest.6:Kamera12:Zoom zu Fuß74:Legt den Zoom der Drittpersonenkamera zu Fuß außerhalb des Kampfes fest.11:Zeitstempel23:Markierungen aktivieren297:Fügt hinter verlinkten Rezepten, Einrichtungsplänen, Handwerksstilen, Stilseiten, Sammlungsstücken und Setteilen ein Symbol ein, wenn sie fehlen. Wählt beim Durchsuchen des Chats eine Nachricht mit einem fehlenden Gegenstand aus und verwendet Anfragen, um eine Flüsternachricht vorzubereiten.5:fehlt23:Could I have $, please?24:Flüsternachricht: <<1>>17:Flüsternachricht174:Legt die Flüsternachricht fest, die beim Drücken von Anfragen vorbereitet wird. Platziert $ an einer beliebigen Stelle in der Nachricht, um den Gegenstandslink einzufügen.30:Filtern Sie den Freundesstatus71:Versteckt Chat-Benachrichtigungen, wenn sich Freunde an- oder abmelden.22:Gildenanzeigen filtern58:Versteckt Chatnachrichten, die einen Gildenlink enthalten.20:+Nachrichten filtern46:Versteckt Chatnachrichten, die mit + beginnen.23:Filtern Sie WTT/WTS/WTB62:Versteckt Handelsnachrichten, die WTT, WTS oder WTB enthalten.27:Gebietsgegenstände filtern110:Blendet Nachrichten im Gebietschat aus, die nur einen einzelnen Gegenstand oder eine einzelne Gilde enthalten.29:Gildenchat wiederhergestellt.27:Gildenchat stummgeschaltet.76:Legt die Farbe der öffentlichen Chat-Nachricht für diesen Gildenslot fest.21:Gildenchat einfärben122:Färbt öffentliche Chat-Nachrichten und Chat-Nachrichten der Offiziersgilde basierend auf der Gilde, aus der sie stammen.12:Gildenfarben98:Wählen Sie für jede aktuelle Gilde die Farben für den öffentlichen Chat und den Offizierschat.31:Gilde <<1>> (nicht beigetreten)11:Gilde <<1>>5:Höhe43:Ändert die Höhe des Gamepad-Chatfensters.20:Horizontale Position59:Verschiebt das Gamepad-Chat-Fenster nach links oder rechts.18:Vertikale Position57