Debuff-Namen der Tracker anzeigen darf.9:Klassisch5:Kampf12:Kampfabsehen13:Begleitrahmen136:Konfigurieren Sie eine benutzerdefinierte Spieler-Infoleiste mit Spieler-ID, Charakter, Championpunkten, Klassennamen und Klassensymbol.61:Konfigurieren Sie Ergänzungen zum Beuteprotokoll des Spiels.68:Konfiguriert Chat, Online-Freunde und die Gruppensuche-Überwachung.67:Konfigurieren Sie Kampftimer, Fadenkreuzoptionen und Integrationen.50:Konfigurieren Sie dedizierte Fortschrittsanzeigen.60:Konfigurieren Sie Angelwarnungen und Lebensqualitätshelfer.77:Konfigurieren Sie Zielregisterkarten, Freeport und Wegschrein-Bestätigungen.50:Konfigurieren Sie gruppenbezogene Automatisierung.58:Konfigurieren Sie Karten-, Minikarten- und GPS-Funktionen.72:Konfigurieren Sie NQOL-Frame-Ersetzungen und Vanilla-Frame-Sichtbarkeit.79:Optionale Kampfintegrationen und weitere verschiedene Funktionen konfigurieren.45:Konfigurieren Sie den Companion-Health-Frame.58:Konfigurieren Sie den Gruppen- und Raid-Gesundheitsrahmen.97:Konfigurieren Sie die Gesundheit, Magicka, Ausdauer und den Reittier-Ausdauerrahmen des Spielers.60:Konfigurieren Sie den Wassertyp-Tracker für seltene Fische.77:Konfigurieren Sie benutzerdefinierte ultimative Countdowns für jeden Balken.75:Steuern Sie Interaktionen beim Reiten und Erinnerungen an das Reittraining.25:Benutzerdefinierte Rahmen89:Passen Sie Chat-Zeitstempel, Verlauf, Fensterplatzierung, Erscheinungsbild und Filter an.61:Passen Sie die Farbe und Form des mittleren Kampfabsehens an.14:Standardrahmen75:Zeigen Sie die einheimische Weltkarte während des Spiels als Minikarte an.12:DLC-Dungeons110:Aktiver Filter führt dazu, sich auf Antiquitäten zu konzentrieren, bei denen Codex-Entdeckungen noch fehlen.6:Angeln13:Angel-Tracker11:Ausrüstung13:Gruppenrahmen11:Gruppierung18:Unendliches Archiv87:Laden Sie Spieler automatisch ein, wenn sie den konfigurierten genauen Chattext senden.77:Listen Sie den Arena-Fortschritt in einer speziellen Fortschrittsanzeige auf.95:Listen Sie