上で上下に移動します。21:戦闘中のズーム120:戦闘中の三人称カメラのズームを設定します。徒歩時と騎乗時の設定より優先されます。6:有効105:現在のプレイ状態に設定された三人称カメラのズームを自動的に適用します。78:各プレイ状態の三人称カメラの自動ズームを設定します。21:騎乗時のズーム81:騎乗中かつ非戦闘時の三人称カメラのズームを設定します。9:カメラ21:徒歩時のズーム81:徒歩中かつ非戦闘時の三人称カメラのズームを設定します。21:タイムスタンプ18:注釈を有効化345:未習得または未取得のレシピ、家具設計図、モチーフ、スタイルページ、コレクション、セット装備のリンク後にアイコンを追加します。チャット閲覧中に未取得アイテムを含むメッセージを選び、「依頼」を使用するとささやきメッセージを準備します。9:未取得23:Could I have $, please?35:ささやきメッセージ：<<1>>27:ささやきメッセージ198:「依頼」を押したときに準備されるささやきメッセージを設定します。メッセージ内の任意の位置に $ を置くと、アイテムリンクが挿入されます。45:友達ステータスをフィルターする102:友達がログオンまたはログオフするときにチャット通知を非表示にします。45:ギルド広告をフィルタリングする81:ギルドリンクを含むチャットメッセージを非表示にします。46:+メッセージをフィルタリングする69:+ で始まるチャット メッセージを非表示にします。27:フィルター WTT/WTS/WTB83:WTT、WTS、または WTB を含む取引メッセージを非表示にします。39:ゾーンアイテムをフィルター121:アイテムまたはギルドが1つだけ含まれるゾーンチャットのメッセージを非表示にします。48:ギルドチャットを再表示しました。51:ギルドチャットを非表示にしました。102:このギルド スロットのパブリック チャット メッセージの色を設定します。33:ギルドチャットの色付け118:公開および役員ギルドのチャット メッセージを、出身ギルドに基づいて色付けします。18:ギルドカラー100:現在の各ギルドのパブリック チャットと役員チャットの色を選択します。29:ギルド<<1>>（未加入）14:ギルド<<1>>6:高さ85:ゲームパッドのチャット ウィンドウの表示高さを変更します。12:水平位置78:ゲームパッドのチャットウィンドウを左右に移動します。9:縦位置78:ゲームパッドのチャットウィンドウを上下に移動します。3:幅91:ゲームパッドのチャット ウィンドウが表示される幅を変更します。51:チャットを開いたままにしておきます229:ゲームプレイ中にテキスト入力を開かなくても、ゲームパッドのチャット ウィンドウを表示したままにします。マップやメニューではチャットは引き続き閉じられます。12:最終 <<1>>90:このギルドスロットの役員チャットメッセージの色を設定します。21:背景を削除する96:ゲームパッドのチャットウィンドウの背景とサイドバーを削除します。6:依頼30:保存されたメッセージ94:リロード後に、この多数の最近のチャット メッセージを復元します。27:ダンジョンで非表示145:4人用ダンジョン内で、全ギルドの一般チャットとオフィサーチャットの受信メッセージを非表示にします。18:試練で非表示129:試練内で、全ギルドの一般チャットとオフィサーチャットの受信メッセージを非表示にします。15:デフォルト4:NQOL6:オフ183:検出可能な他のタイムスタンプをNQOLのものに置き換えるか、タイムスタンプを変更しないか、削除するかを選択します。NQOL形式: <<1>>。15:ささやき声94:着信および発信のささやきのチャット メッセージの色を設定します。21:背景の不透明度69:リマインダー表示の背景の不透明度を調整します。18:枠線のサイズ122:リマインダーの表示枠の太さを変更します。境界線を非表示にするには、0 に設定します。18:すべてクリア42:すべてのリマインダーをクリア85:保存されているすべてのチャット リマインダーを削除します。36:リマインダーを有効にする78:チャットウィンドウのリマインドボタンを有効にします。27:リマインダーの設定78:チャットリマインダーとその画面上の表示を設定します。12:フォント21:フォントサイズ63:リマインダーの表示文字サイズを変更します。75:リマインダー表示で使用されるフォントを変更します。18:ヘッダーの色81:リマインダーの表示タイトルと区切り線の色を変更します。12:水平位置54:リマインダー表示を左右に移動します。39:リマインダーはありませ