tes potenciales activos137:Agrega Mostrar falta a Todos los clientes potenciales activos, mostrando solo antigüedades sin ninguna entrada del códice desbloqueada.17:Pista ya excavada34:Indicadores de pistas del mercader156:Muestra un reloj de arena para las pistas que ya tienes y una marca verde para las que ya has excavado. Si se dan ambas condiciones, los iconos se alternan.18:Pista en posesión18:Opacidad del fondo72:Ajusta qué tan opaco es el fondo del rastreador de Mejoras/Desventajas.10:Habilitado71:Carga y muestra el rastreador de ventajas/desventajas durante el juego.6:fuente17:Tamaño de fuente61:Cambia el tamaño de los nombres de las ventajas/desventajas.67:Elige la fuente utilizada para los nombres de ventajas/desventajas.20:posición horizontal92:Mueve la tabla de ventajas/desventajas hacia la izquierda o hacia la derecha en la pantalla.13:monitor mayor77:Muestra la columna Efecto principal en el rastreador de ventajas/desventajas.13:monitor menor73:Muestra la columna Efecto menor en el rastreador de ventajas/desventajas.98:Permite que el rastreador muestre <<1>> filas de mejora cuando la pista seleccionada está activa.103:Permite que el rastreador muestre <<1>> filas de desventajas cuando la pista seleccionada está activa.25:Mostrar en configuración129:Mantiene la tabla de ventajas/desventajas visible aquí para que se puedan obtener una vista previa de los cambios de ubicación.4:pila132:Controla si las filas de Mejoras/Desventajas se expanden hacia abajo desde el borde superior o hacia arriba desde el borde inferior.19:Seguimiento de todo27:Seguimiento si está activo18:Pista seleccionada4:Modo119:Controla si el rastreador muestra todos los efectos monitoreados, solo los efectos activos o los efectos seleccionados.22:Usar íconos de juegos144:Muestra iconos de efectos ESO. Cuando está desactivado, los efectos mayores usan marcadores rojos y los efectos menores usan marcadores verdes.18:posición vertical81:Mueve la tabla de ventajas/desventajas hacia arriba o