    ru = "24:Загружен v<<1>>.22:ПРИОБРЕТАНО16:АКТИВНЫЙ10:После20:Аналоговый8:Авто18:Доступный4:До12:Нижний15:Низ-Верх12:Отмена20:Челленджер16:Характер25:имя персонажа8:Круг18:Завершено24:Подтверждать22:Расширенный14:Базовый8:Даты12:Полный13:<<1>> - <<2>>10:Алмаз16:Цифровой18:Увольнять12:Равный28:Дополнительный14:Фрипорт16:Шестерня27:Групповой кадр18:Миникарта12:Маунты22:обеспечение22:Антиквариат27:Геймпад жирный35:Подсветка геймпада29:Геймпад средний20:Рукописный33:Клавиатура жирная35:Клавиатура средняя10:Общий12:Золото25:Сложный режим31:Сложный режим <<1>>28:Горизонтальный19:В процессе29:Набор предметов16:предметы16:ИЗВЕСТНО10:Левый26:Заблокировано12:%.0f мин.13:<<1>> мин.22:ОТСУТСТВУЕТ6:Нет19:Нет смерти6:Нет20:Нормальный25:НЕ ПРИОБРЕТЕН20:Недоступно23:Не завершено27:Не установлено33:Не поддерживается12:ничего10:Число22:Выключенный14:Процент39:идентификатор игрока47:Предварительный просмотр22:Родственник10:Верно29:Правый джойстик10:Поиск12:%.0f сек.18:ВЫБРАННЫЕ37:Установить активным22:<<1>> показано16:Скорость14:Квадрат28:Поддерживается14:Вершина15:Верх-Низ22:Путешествия16:Трифекта20:НЕИЗВЕСТНО20:Неизвестно28:Разблокировано24:Использовать27:ID пользователя13:НКЖ v<<1>>24:Вертикальный14:Ветеран4:Да49:Точный текст через запятую286:Вы успешно установили NQOL. Настройки по умолчанию ни на что не влияют в игре. Вам необходимо вручную включить необходимые функции NQOL через «Параметры» > «NQOL».43:Добро пожаловать в НКОЛ170:Чтобы изменить язык NQOL, необходимо перезагрузить интерфейс. Перезагрузить интерфейс сейчас?26:Изменить язык?164:Сбросить текущий прирост золота за сессию, скорость золота в минуту и ​​историю графика?162:Сбросить текущий прирост опыта за сессию, процент опыта за минуту и ​​историю графиков?19:Что нового27:Что нового в NQOL17:Авто-глаз206:Автоматически использует «Глаз антиквара», когда его можно использовать на активном месте раскопок древностей.23:Показать все43:Показать отсутствующие49:Фильтр всех активных лидов270:Добавляет «Показать отсутствующие» ко всем активным зацепкам, отображая только предметы старины, в которых нет разблокированной записи в кодексе.40:Зацепка уже раскопана57:Индикаторы зацепок у торговцев250:Показывает песочные часы для полученных зацепок и зелёную галочку для уже раскопанных. Если применимы оба состояния, значки чередуются.38:Зацепка уже получена37:Непрозрачность фона108:Регулирует непрозрачность фона трекера усилений/дебаффов.16:Включено115:Загружает и показывает трекер усилений/дебаффов во время игры.10:Шрифт25:Размер шрифта81:Изменяет размер названий усилений/дебаффов.112:Выбирает шрифт, используемый для названий усилений/дебаффов.47:Горизонтальное положение119:Перемещает таблицу усилений/дебаффов влево или вправо по экрану.29:Главный монитор124:Показывает столбец «Основной эффект» на трекере усилений/дебаффов.43:Незначительный монитор118:Показывает столбец «Малый эффект» на трекере усилений/дебаффов.146:Позволяет трекеру отображать строки усиления <<1>>, когда выбранный трек активен.146:Позволяет трекеру отображать строки дебаффов <<1>>, когда выбранный трек активен.40:Показать в настройках212:Здесь отображается таблица усилений/дебаффов, чтобы можно было предварительно просмотреть изменения в размещении.8:Стек195:Определяет, будут ли строки усилений/дебаффов расширяться вниз от верхнего края или вверх от нижнего края.31:Отслеживайте все47:Отслеживать, если активно21:Трек выбран10:Режим197:Определяет, отображает ли трекер все отслеживаемые эффекты, только активные эффекты или выбранные эффекты.50:Используйте игровые значки287:Показывает значки эффектов ESO. Если параметр отключен, для основных эффектов используются красные маркеры, а для второстепенных эффектов — зеленые маркеры.43:Вертикальное положение115:Перемещает таблицу усилений/дебаффов вверх или вниз по экрану.24:Масштаб в бою190:Задаёт масштаб камеры от третьего лица в бою. Этот уровень имеет приоритет над уровнями пешком и верхом.16:Включено180:Автоматически применяет настроенный масштаб камеры от третьего лица для текущего состояния игры.176:Настраивает автоматические уровни масштаба камеры от третьего лица для каждого состояния игры.27:Масштаб верхом99:Задаёт масштаб камеры от третьего лица верхом вне боя.12:Камера27:Масштаб пешком99:Задаёт масштаб камеры от третьего лица пешком вне боя.25:Метка времени31:Включить отметки502:Добавляет значок после ссылок на отсутствующие рецепты, чертежи обстановки, мотивы, страницы стилей, коллекционные предметы и части комплектов. При просмотре чата выберите сообщение с отсутствующим предметом и используйте «Запросить», чтобы подготовить личное сообщение.22:отсутствует23:Could I have $, please?38:Личное сообщение: <<1>>31:Личное сообщение267:Задаёт личное сообщение, которое подготавливается при нажатии «Запросить». Поместите $ в любое место сообщения, чтобы вставить ссылку на предмет.46:Фильтровать статус друга139:Скрывает уведомления чата, когда друзья входят в систему или выходят из нее.58:Фильтровать объявления гильдий100:Скрывает сообщения чата, содержащие ссылку на гильдию.42:Фильтровать +сообщения76:Скрывает сообщения чата, начинающиеся с +.24:Фильтр WTT/WTS/WTB95:Скрывает торговые сообщения, содержащие WTT, WTS или WTB.60:Фильтровать предметы в чате зоны138:Скрывает сообщения в чате зоны, содержащие только один предмет или гильдию.47:Чат гильдий восстановлен.39:Чат гильдий отключён.129:Устанавливает цвет сообщений публичного чата для этого слота гильдии.42:Раскрасить чат гильдии205:Раскрашивает сообщения публичного чата и чата офицеров гильдии в зависимости от гильдии, из которой они пришли.25:Цвета гильдии136:Выбирайте цвета публичного и офицерского чата для каждой текущей гильдии.44:Гильдия <<1>> (не вступила)20:Гильдия <<1>>12:Высота65:Изменяет высоту окна чата геймпада.47:Горизонтальное положение87:Перемещает окно чата геймпада влево или вправо.43:Вертикальное положение83:Перемещает окно чата геймпада вверх или вниз.12:Ширина65:Изменяет ширину окна чата геймпада.38:Держите чат открытым231:Сохраняет окно чата геймпада видимым во время игры, не открывая ввод текста. Чат по-прежнему закрывается на картах и ​​в меню.24:Последний <<1>>126:Устанавливает цвет сообщения в чате офицера для этого слота гильдии.21:Удалить фон88:Удаляет фон и боковую панель окна чата геймпада.18:Запросить41:Сохраненные сообщения144:Восстанавливает такое количество недавних сообщений чата после перезагрузки.44:Отключать в подземельях188:Скрывает входящие сообщения общего и офицерского чатов всех гильдий в подземелье для четырёх игроков.42:Отключать в испытаниях149:Скрывает входящие сообщения общего и офицерского чатов всех гильдий в испытании.23:По умолчанию4:NQOL9:Выкл.260:Выбирает, будет ли NQOL заменять другие распознаваемые метки времени своей, оставлять метки времени без изменений или удалять их. Формат NQOL: <<1>>.10:Шепот125:Устанавливает цвет сообщений чата для входящих и исходящих шепотов.37:Непрозрачность фона120:Регулирует степень непрозрачности фона отображения напоминаний.27:Размер границы174:Изменяет толщину границы отображения напоминаний. Установите значение 0, чтобы скрыть границу.23:Очистить все46:Очистить все напоминания80:Удаляет все сохраненные напоминания о чате.39:Включить напоминания74:Включает кнопку «Напомнить» в окне чата.41:Настройка напоминаний103:Настройте напоминания в чате и их отображение на экране.10:Шрифт25:Размер шрифта66:Изменяет размер текста напоминаний.107:Изменяет шрифт, используемый для отображения напоминаний.27:Цвет заголовка117:Изменяет заголовок отображения напоминаний и цвет разделителя.47:Горизонтальное положение98:Перемещает отображение напоминаний влево или вправо.38:Никаких напоминаний.18:Напомнить41:Напоминание добавлено22:Напоминания14:Удалить28:Показать в игре69:Показывает напоминания во время игры.40:Показать в настройках206:Здесь отображается отображение напоминаний, чтобы можно было предварительно просмотреть изменения размещения.21:Цвет текста113:Изменяет цвет текста сообщения, отображаемого напоминаниями.43:Вертикальное положение94:Перемещает отображение напоминаний вверх или вниз.12:Ширина76:Изменяет ширину отображения напоминаний.27:Перенос текста150:Переносить текст напоминаний на несколько строк вместо сокращения с помощью «...».85:Лучший прогресс: |c<<1>>Arc <<2>> · Цикл <<3>> · Этап <<4>>|r81:Лучший прогресс: Дуга <<1>> · Цикл <<2>> · Этап <<3>>47:Лучший результат: |c<<1>><<2>>|r38:Лучший результат: <<1>>33:Бесконечный архив30:Лучшее в журнале220:Регистрирует текущий сохраненный лучший результат Бесконечный архив и прогресс, когда мониторинг становится активным.27:Начало журнала154:Записывает сообщение чата, когда мониторинг Бесконечный архив становится активным.33:Остановка журнала272:Записывает сообщение чата, когда мониторинг оценок Бесконечный архив прекращается после завершения, выхода или отключения отслеживания прогресса.56:Мониторинг оценок активен: <<1>>.69:Лучшее в новом бесконечном архиве: <<1>>60:Новый Бесконечный Архив, лучшее -107:Пока нет сохраненных <<1>> лучших результатов или прогресса.152:Пробег изменен с SOLO на DUO. Отслеживание оценок и прогресса было реклассифицировано.47:Сохранено <<1>> лучшее · <<2>>.55:Мониторинг оценок остановлен.50:Мониторинг оценок активен -41:Отслеживайте прогресс286:Включает мониторинг событий Бесконечный архив для получения лучших результатов по всей учетной записи, а также самых высоких значений дуги, цикла и стадии.37:Поворот зеркал LC Crutch251:При использовании Crutch Alerts в <<1>> с включёнными номерами зеркал Орфика размещение поворачивается на 180 градусов (то есть вход/юг = зеркало 1).18:Компаньон9:Выкл.7:Вкл.23:Вкл. и журнал29:Закрытие ошибок29:Показать ошибку259:Предотвращает появление окон ошибок Lua. Вкл. и журнал записывает заголовок каждой ошибки в чат; выберите его, чтобы показать ошибку полностью.54:Автоматический выбор наживки177:Автоматически выбирает самую известную наживку при нацеливании на распознанную рыболовную яму.37:Непрозрачность фона89:Регулирует непрозрачность фона трекера рыбалки.33:Рыболовный трекер10:Шрифт25:Размер шрифта73:Изменяет размер текста трекера рыбалки.86:Выбирает шрифт, используемый трекером рыбалки.47:Горизонтальное положение98:Перемещает трекер рыбалки влево или вправо по экрану.16:Включено20:Ориентация232:Позволяет выбрать, будет ли трекер рыбалки располагать типы водоемов вертикально или отображать их в один горизонтальный ряд.40:Показать в настройках195:Здесь остается видимым трекер рыбалки, чтобы можно было предварительно просмотреть изменения размещения.171:Управляет отображением трекера рыбалки. Авто показывает это при нацеливании на рыбацкую яму.43:Вертикальное положение94:Перемещает трекер рыбалки вверх или вниз по экрану.8:авто9:выкл.4:на28:Горизонтальный24:Вертикальный42:Уведомление о барабане31:Звук уведомления141:Выбор встроенного игрового звука, который воспроизводится, когда улов готов.188:Показывает большой анимированный значок рыбалки и воспроизводит звук, когда улов готов к вытягиванию.47:Сообщить о смене приманки183:Показывает сообщение в центре экрана, когда автоматический выбор наживки меняет выбранную наживку.35:Способность готова37:Достижение получено41:Ошибка предупреждения27:Чемпион предан54:Коллекционный предмет открыт25:Дуэль принята27:Дуэль началась39:Бонус справедливости31:Повышение уровня26:Метка на карте33:Новое уведомление29:Цель обнаружена35:Положительный клик27:Квест завершен43:Камни Тель-Вар получены37:Испытание завершено45:Суперспособность готова85:Переключение на <<1>> приманку для типа лунки <<2>>12:Отмена22:Подтвердить82:Платное резервное подтверждение недоступно.50:Резервный вариант Фрипорта73:Для <<1>> бесплатный телепорт не доступен.49:Местоположение не выбрано.97:В <<1>> других игроков нет. Этот телепорт будет платным.92:Для <<1>> не найдено доступного дорожного святилища.23:целевая зона41:Перешел в <<1>> через <<2>>.87:Путешествие по Дорожному святилищу недоступно.37:Непрозрачность фона110:Регулирует степень непрозрачности фона отображения друзей.27:Размер границы164:Изменяет толщину границы отображения друзей. Установите значение 0, чтобы скрыть границу.37:Персонаж недоступен43:Подробности недоступны16:Включено72:Показывает онлайн-друзей во время игры.12:Друзья67:Настройте отображение друзей в сети.10:Шрифт25:Размер шрифта78:Изменяет размер текста на экране «Друзья».97:Выбирает шрифт, используемый для отображения друзей.12:Друзья27:Цвет заголовка152:Изменяет заголовок отображения друзей, счетчик, разделитель и цвет значка статуса.47:Горизонтальное положение88:Перемещает отображение друзей влево или вправо.27:Видимые строки157:Ограничивает количество отображаемых друзей в сети до того, как список будет обрезан.31:Нет друзей в сети18:<<1>> онлайн25:Имя персонажа130:Показывает имена активных персонажей онлайн-друзей, если они доступны.53:Показать друзей в настройках184:Здесь отображается список друзей, поэтому можно предварительно просмотреть изменения в размещении.27:Значок статуса147:Рядом с каждым другом отображается значок «Онлайн», «Нет на месте» или «Занято».8:Зона104:Показывает текущие зоны друзей в сети, если они доступны.21:Цвет текста88:Изменяет цвет текста строки отображения друзей.43:Вертикальное положение84:Перемещает отображение друзей вверх или вниз.12:Ширина66:Изменяет ширину отображения друзей.35:Локация недоступна45:Автоматическая привязка226:Связывает недавно добытое несвязанное снаряжение из комплекта, если с его помощью можно разблокировать предмет коллекции.43:Автоматическая зарядка182:Использует заполненный камень душ, когда заряд экипированного оружия достигает выбранного порога.20:Авторемонт186:Использует ремонтный набор, когда прочность надетого элемента доспехов достигает выбранного порога.25:Связанный <<1>>.23:Порог заряда147:Задаёт процент заряда, при котором автозаряд использует заполненный камень душ.21:Заряжен <<1>>.31:Привязка журнала151:Пишет сообщение в чат, когда автоматическая привязка успешно привязывает элемент.25:Журнал заряда120:Пишет сообщение в чат, когда автозарядка успешно заряжает оружие.29:Ремонт журналов150:Пишет сообщение в чат, когда автовосстановление успешно восстанавливает предмет.55:Ремонтировать всё у торговцев208:Автоматически ремонтирует всё повреждённое снаряжение за золото при разговоре с торговцем, предлагающим ремонт.25:Порог ремонта142:Задаёт процент прочности, при котором авторемонт использует ремонтный набор.25:Исправлен <<1>>.35:Расширенные данные890:Используется фиксированный 38-символьный формат E4 в системе с основанием 45: E4, зона (3), мировые X/Y/Z (по 4), направление игрока/камеры в миллирадианах (по 3), отпечаток взаимодействия (6), флаги взаимодействия (1), состояния семи ремесленных заказов (3), активный тип ремесла (1), состояние интерфейса (1), флаги телеметрии (1) и контрольная сумма (2). Текст взаимодействия хешируется, а цели-юниты исключаются. Данные учётной записи и персонажа не включаются. Если отключено, QR-код содержит только X, Y и Z.60:Расширенные данные QR недоступны.8:Цвет58:Изменяет цвет текста GPS и QR-кода.8:X: <<1>>8:Y: <<1>>8:Z: <<1>>35:Формат отображения226:Выбирает отображение текущих глобальных координат в виде QR-кода, обычного текста или значений CSV. Для QR-кодов требуется LibQRC.20:Включить GPS110:Показывает текущие глобальные координаты LibGPS во время игры.108:Настраивает отображение текущих глобальных координат LibGPS.10:Шрифт25:Размер шрифта73:Изменяет размер текста GPS и координат CSV.71:Изменяет шрифт текста GPS и координат CSV.20:Значения CSV9:QR-код25:Обычный текст47:Горизонтальное положение89:Перемещает дисплей GPS влево или вправо по экрану.65:Текущее местоположение недоступно.3:GPS28:Непрозрачность65:Изменяет непрозрачность дисплея GPS.26:Горизонтально20:Ориентация181:Выбирает отображение текстовых координат в одной горизонтальной строке или вертикальном столбце.22:Вертикально30:X: <<1>>   Y: <<2>>   Z: <<3>>45:Не удалось создать QR-код.24:Размер QR-кода96:Изменяет ширину и высоту квадратного дисплея QR-кода.9:QR-код10:Текст44:Показывать в настройках213:Оставляет дисплей GPS видимым на этой странице настроек, чтобы можно было просматривать изменения при отключённом GPS.105:Недоступно, поскольку LibGPS не установлена или не включена.174:Для QR-кодов требуется LibQRC. Установите и включите её либо выберите обычный текст или значения CSV.35:Частота обновления232:Задаёт частоту проверки координат GPS. Меньшие значения обновляют данные чаще и могут потреблять больше процессорного времени.9:%.0f мс43:Вертикальное положение85:Перемещает дисплей GPS вверх или вниз по экрану.12:Сигнал23:Звук сигнала198:Выбирает встроенный игровой звук, который воспроизводится, когда объявление совпадает с сигнальным словом.25:Текст сигнала32:Текст сигнала: <<1>>51:Введите слова через запятую163:Задаёт разделённые запятыми слова для поиска в местах, названиях и описаниях объявлений.190:Воспроизводит звук и выделяет объявления, в месте, названии или описании которых есть сигнальное слово.37:Непрозрачность фона104:Настраивает непрозрачность фона монитора поиска группы.23:Размер рамки146:Изменяет толщину рамки монитора поиска группы. Установите 0, чтобы скрыть рамку.18:Категории69:Проверяет объявления категории «<<1>>».45:Проверка поиска группы...46:Закрывать при вступлении141:Закрывает монитор поиска группы и отключает его, когда вы вступаете в группу.16:Включено158:Проверяет выбранные категории поиска группы и показывает их объявления во время игры.40:Монитор поиска группы142:Выберите объявления поиска группы для отслеживания и настройте их интерфейс.32:Фильтры и сигналы10:Шрифт71:Выбирает шрифт монитора поиска группы.47:Горизонтальное положение93:Перемещает монитор поиска группы влево или вправо.23:Поиск группы27:Объявлений: <<1>>35:Видимые объявления116:Ограничивает количество объявлений в вертикальном интерфейсе.6:Все9:Выкл.22:Отслеживать10:Новое105:Выберите хотя бы одну категорию, чтобы начать мониторинг.54:Подходящие группы не найдены.4:ДД8:Роль141:Показывает только объявления с ролями, где ещё есть место для выбранной роли.17:<<1>>  •  <<2>>14:Масштаб111:Изменяет размер всего монитора поиска группы, включая текст.44:Показывать в настройках187:Оставляет монитор поиска группы видимым здесь для предпросмотра изменений положения и внешнего вида.26:Проверка: <<1>>...14:Активно24:Активно • <<1>>10:Пауза24:Предпросмотр46:Восстановление фильтра...45:Остановить отслеживание43:Вертикальное положение89:Перемещает монитор поиска группы вверх или вниз.12:Ширина100:Изменяет ширину вертикального монитора поиска группы.39:Отклоненная задержка295:Устанавливает, сколько минут ждать перед автоматическим приглашением игрока, который отклонил приглашение. Установите значение 0, чтобы отключить эту задержку.25:Размер группы255:Устанавливает максимальный размер группы. После достижения этого размера дальнейшие запросы на автоматическое приглашение игнорируются.20:Войти в чат108:Показывает отправленные автоматические приглашения в чат.10:Режим172:Выбирает, какие входящие каналы чата могут инициировать автоматическое приглашение в группу.60:Задержка повторного приглашения273:Устанавливает, сколько минут ждать перед автоматическим приглашением уже приглашенного игрока. Установите значение 0, чтобы отключить эту задержку.244:Устанавливает один или несколько точных текстов чата, которые вызывают приглашение в группу. Разделяйте несколько текстов запятыми.12:<<1>> мин9:Выкл.9:1 мин.51:Автоматическое приглашение24:Приглашенный105:Приглашен <<1>> после запроса автоматического приглашения.49:только в личных сообщениях14:DM и зона22:Выключенный21:Только зона12:Сказал16:Текст <<1>>311:Запускает инкрементную сборку мусора Lua по фоновому таймеру, когда использование памяти аддона составляет не менее 60%. Выбегает только вне боя и не чаще, чем раз в 10 минут.37:Обход подтверждения192:Пропускает всплывающее окно подтверждения при быстром путешествии или возвращении в путевое святилище.50:Резервный вариант Фрипорта151:Управляет действиями Фрипорта, когда в целевой зоне нет друзей или членов гильдии.14:Фрипорт272:Добавляет кнопку «Свободный порт» к локациям на карте и дорожным святилищам, позволяющую свободно телепортироваться через друзей и членов гильдии.41:Показывать подземелья193:Добавляет на карту вкладку «Подземелья» с разделами подземелий и арен для путешествия к открытым местам.39:Показывать испытания144:Добавляет на карту вкладку «Испытания» для путешествия к открытым испытаниям.17:Шоу-центр25:Не показывать42:Шрифт названия области109:Изменяет шрифт, используемый в названии области мини-карты.31:Название региона129:Выбор места отображения текущей области и названия зоны на мини-карте.38:Размер имени области124:Изменяет размер текста, используемый в названии области мини-карты.27:Показать слева35:Показать правильно23:Цвет границы61:Изменяет цвет границы мини-карты.27:Размер границы146:Изменяет толщину границ мини-карты. Установите значение 0, чтобы скрыть границу.53:Размер маркера в подземельях84:Изменяет размер маркера игрока в подземельях.20:Подземелья179:Устанавливает масштаб мини-карты в подземельях. Более высокие значения сильнее приближают карту.35:Включить миникарту162:Показывает собственные плитки и метки карты мира на обрезанной мини-карте во время игры.14:Быстрый25:Самый быстрый20:Нормальный18:Медленный29:Самый медленный55:Совместимость с картой урожая227:Позволяет HarvestMap рассматривать NQOL как совместимую мини-карту, чтобы на ней могли отображаться контакты включенных ресурсов.47:Горизонтальное положение90:Перемещает мини-карту влево или вправо по экрану.40:Размер маркера верхом103:Изменяет размер маркера игрока при передвижении верхом.12:Верхом198:Устанавливает масштаб мини-карты при передвижении верхом. Более высокие значения сильнее приближают карту.26:Показать в бою77:Сохраняет мини-карту видимой во время боя.59:Показать миникарту в настройках217:Показывает мини-карту на этом экране настроек, чтобы можно было просмотреть изменения, даже если мини-карта отключена.12:Размер78:Изменяет размер окна просмотра мини-карты.45:Размер маркера в подзоне114:Изменяет размер маркера игрока при отображении карты подзоны.14:Подзона209:Устанавливает масштаб мини-карты при отображении карты подзоны. Более высокие значения сильнее приближают карту.79:Недоступно, пока активна мини-карта Вотана.35:Частота обновления268:Выбирает, как часто мини-карта определяет ваше положение. Более быстрые обновления выполняются более плавно, но требуют больше времени обработки.43:Вертикальное положение85:Перемещает миникарту вверх или вниз по экрану.91:Миникарта Вотана активна. Миникарта NQOL отключена.19:Цвет линии96:Изменяет цвет пунктирной линии дорожного святилища.16:Включено160:Рисует пунктирной линией ближайшее обнаруженное дорожное святилище в открытом PvE-мире.25:Толщина линии102:Изменяет толщину пунктирной линии дорожного святилища.39:Размер маркера в зоне108:Изменяет размер маркера игрока при отображении карты зоны.8:Зона203:Устанавливает масштаб мини-карты при отображении карты зоны. Более высокие значения сильнее приближают карту.66:Разрешить взаимодействия «Открыть»171:Разрешает взаимодействия с действием «Открыть», когда включена функция «Оставаться верхом».72:Разрешить взаимодействия «Поговорить»177:Разрешает взаимодействия с действием «Поговорить», когда включена функция «Оставаться верхом».76:Разрешить взаимодействия «Использовать»181:Разрешает взаимодействия с действием «Использовать», когда включена функция «Оставаться верхом».54:Спешьтесь для взаимодействия47:Оставаться установленным214:Блокирует подсказки взаимодействия верхом, чтобы предотвратить случайное спешивание, кроме разрешённых ниже типов.64:Доступна тренировка верховой езды.33:Проверка обучения185:Напоминает, когда этот персонаж может тренировать скорость езды, выносливость или грузоподъемность.39:Интенсивность полосы41:Непрозрачность полосы94:Устанавливает интенсивность классических полосок.92:Устанавливает непрозрачность классических полос.27:Размер границы95:Устанавливает толщину границы классической полосы.21:Высота бара76:Устанавливает высоту классических полос.175:Выбирает, будут ли классические текущие значения ресурсов отображаться в цифрах или процентах.44:Шрифт летающей анимации55:Размер шрифта анимации полета83:Изменяет размер классических летающих чисел.117:Выбирает шрифт, используемый классическими летающими номерами.54:Летающая негативная анимация105:Показывает летающие цифры, когда ресурс Classic уменьшается.54:Летающая позитивная анимация100:Показывает летающие числа при увеличении ресурса Classic.10:Шрифт25:Размер шрифта72:Изменяет размер значений ресурсов Classic.119:Выбирает шрифт, используемый классическими значениями ресурсов.29:Ширина здоровья93:Устанавливает ширину классической шкалы здоровья.23:Ширина магии87:Устанавливает ширину шкалы классической магии.31:Разделение баров151:Устанавливает расстояние между центральной полосой здоровья и боковыми полосами.37:Ширина выносливости84:Устанавливает ширину шкалы выносливости Classic.103:Устанавливает интенсивность шкалы здоровья компаньона.105:Устанавливает непрозрачность шкалы здоровья компаньона.27:Размер границы106:Устанавливает толщину границы шкалы здоровья компаньона.154:Выбирает, будет ли текущее здоровье компаньона отображаться в цифрах или процентах.10:Шрифт25:Размер шрифта146:Изменяет размер текста, используемый на панели здоровья сопутствующего товара.107:Выбирает шрифт, используемый полосой здоровья компаньона.73:Задает цвет полосы здоровья компаньона.12:Высота89:Устанавливает высоту шкалы здоровья компаньона.20:Ориентация169:Выбирает, будет ли полоса здоровья компаньона располагаться горизонтально или вертикально.12:Реверс224:Меняет направление заполнения шкалы здоровья компаньона на противоположное и перемещает имя на противоположную сторону.35:Интенсивность тени131:Устанавливает, насколько сильной будет тень шкалы здоровья компаньона.8:Тень166:Добавляет прогрессивную внутреннюю тень вдоль выбранного края шкалы здоровья компаньона.40:Показать в настройках237:Здесь отображается персонализированный сопутствующий фрейм, чтобы можно было предварительно просмотреть изменения размещения.23:Показать имя95:Показывает имя компаньона рядом со шкалой здоровья.33:Уровень отношений161:Показывает текущий уровень и общий прогресс отношений с компаньоном рядом с его именем.27:Прогресс опыта130:Показывает прогресс опыта компаньона на шкале под его шкалой здоровья.12:Ширина89:Устанавливает ширину шкалы здоровья компаньона.19:Цвет опыта65:Задает цвет шкалы опыта компаньона.31:Текущее значение99:Устанавливает непрозрачность панели здоровья группы.27:Размер границы113:Устанавливает толщину границы строки здоровья каждой группы.25:Размещение КП164:Выбирает, будут ли отображаться чемпионские очки до или после имени каждого члена группы.191:Выбирает, будет ли текущее состояние здоровья каждого члена группы отображаться в цифрах или процентах.32:Цвет дилера урона123:Устанавливает цвет шкалы здоровья для членов группы дилеров урона.18:Затемнить188:Устанавливает непрозрачность для членов группы, находящихся за пределами диапазона поддержки группы.10:Шрифт25:Размер шрифта118:Изменяет размер текста, используемый строками состояния группы.103:Выбирает шрифт, используемый строками состояния группы.25:Цвет целителя116:Устанавливает цвет шкалы здоровья для членов группы целителей.12:Высота98:Устанавливает высоту строки состояния каждой группы.23:Показать имя173:Выбирает, будут ли в строках группы отображаться идентификаторы игроков или имена персонажей.33:Воскрешающий цвет144:Устанавливает цвет шкалы здоровья, используемый при воскрешении члена группы.12:Реверс98:Меняет направление заполнения шкалы здоровья группы.40:Разрыв между строками108:Устанавливает расстояние между строками состояния группы.156:Добавляет прогрессивную внутреннюю тень вдоль выбранного края каждой панели группы.17:Цвет щита124:Задает цвет активных щитов, отображаемых на шкалах здоровья группы.21:Показать КП111:Добавляет к имени каждого члена группы его чемпионские очки.27:Показать класс117:Добавляет к имени каждого члена группы значок класса персонажа.35:Показать спутников175:Показывает значок компаньона и имя компаньона рядом с участниками группы, у которых он активен.60:Показать пользовательские имена311:Показывает псевдонимы LibCustomNames для членов группы, у которых они есть, в противном случае сохраняется выбранный идентификатор игрока или имя персонажа. Требуется LibCustomNames.46:Показать счетчик смертей163:Показывает количество смертей каждого члена группы за пределами строки здоровья группы.40:Показать в настройках217:Здесь отображается рамка пользовательской группы, чтобы можно было предварительно просмотреть изменения размещения.17:Шоу-лидер127:Показывает корону за пределами строки здоровья группы лидера группы.44:Не показывать исцеления112:Показывает наложение без лечения на строках здоровья группы.39:Показать воскрешение138:Выделяет участников группы, пока они воскрешаются или ожидают воскрешения.23:Показать щит161:Показывает активный щит каждого участника группы в виде сегмента на его шкале здоровья.40:Показывать метку цели180:Показывает метку цели, назначенную каждому участнику группы, внутри его групповой шкалы здоровья.29:Показать травму159:Показывает недоступное здоровье в виде сегмента травмы в строках группового здоровья.17:Цвет бака110:Устанавливает цвет шкалы здоровья для членов группы танков.21:Цвет травмы171:Устанавливает цвет недоступного здоровья, отображаемого травмой на полосах здоровья группы.12:Ширина85:Устанавливает ширину строки состояния группы.25:Цвет здоровья65:Задает цвет полосы здоровья игрока.47:Горизонтальное положение107:Перемещает пользовательский кадр игрока влево или вправо.19:Цвет магии59:Задает цвет полосы магии игрока.45:магическая выносливость24:Классический31:Выбранный пресет16:Пирамида20:Радиальный8:Куча94:Выбирает, как NQOL складывает полосы ресурсов игрока.24:Вертикальный82:Устанавливает интенсивность полос пирамиды.90:Устанавливает непрозрачность стержней пирамиды.27:Размер границы87:Устанавливает толщину границы панели пирамиды.167:Выбирает, будут ли текущие значения ресурсов пирамиды отображаться в цифрах или процентах.44:Шрифт летающей анимации55:Размер шрифта анимации полета75:Изменяет размер летающих чисел пирамиды.105:Выбирает шрифт, используемый летающими числами пирамиды.54:Летающая негативная анимация114:Показывает летающие числа, когда ресурс пирамиды уменьшается.54:Летающая позитивная анимация109:Показывает летающие числа при увеличении ресурса пирамиды.10:Шрифт25:Размер шрифта72:Изменяет размер значений ресурсов Pyramid.100:Выбирает шрифт, используемый значениями ресурсов Pyramid.29:Высота здоровья85:Устанавливает высоту шкалы здоровья пирамиды.29:Ширина здоровья85:Устанавливает ширину шкалы здоровья пирамиды.23:Ширина магии81:Устанавливает ширину полосы магии пирамиды.48:Высота магии/выносливости111:Устанавливает высоту полосок магии и выносливости Пирамиды.37:Ширина выносливости93:Устанавливает ширину шкалы выносливости пирамиды.44:Шрифт летающей анимации55:Размер шрифта анимации полета79:Изменяет размер радиальных летающих чисел.84:Выбирает шрифт для радиальных летающих чисел.54:Летающая негативная анимация115:Показывает летающие числа при уменьшении радиального ресурса.54:Летающая позитивная анимация115:Показывает летающие числа при увеличении радиального ресурса.12:Реверс35:Интенсивность тени95:Устанавливает, насколько сильной будет тень панели.8:Тень185:Добавляет прогрессивную внутреннюю тень вдоль выбранного края каждой полосы в этом наборе настроек.17:Цвет щита107:Задает цвет щита, отображаемого на полосе здоровья игрока.40:Показать в настройках215:Здесь отображается пользовательский кадр игрока, чтобы можно было предварительно просмотреть изменения размещения.44:Не показывать исцеления110:Показывает наложение без лечения на полосе здоровья игрока.16:Включено98:Показывает облегченную шкалу здоровья компаньона NQOL.16:Включено100:Показывает облегченную структуру состояния группы NQOL.16:Включено94:Показывает облегченные панели ресурсов игроков NQOL.43:Показывать только в бою75:Показывает эту рамку только во время боя.23:Показать щит122:Показывает активный щит игрока в виде сегмента на полосе здоровья.29:Показать травму149:Показывает недоступное здоровье в виде сегмента травмы на шкале здоровья игрока.31:Плавные переходы144:Анимирует изменения значений панели вместо прямой привязки к новому значению.80:Устанавливает интенсивность полосок стека.78:Устанавливает непрозрачность полос стека.27:Размер границы81:Устанавливает толщину границы панели стека.161:Выбирает, будут ли текущие значения ресурсов стека отображаться в цифрах или процентах.44:Шрифт летающей анимации55:Размер шрифта анимации полета69:Изменяет размер летающих чисел стека.99:Выбирает шрифт, используемый летающими числами стека.54:Летающая негативная анимация108:Показывает летающие числа, когда ресурс стека уменьшается.37:Летающая ориентация227:Выбирает, начинаются ли летающие числа стека за пределами левой или правой стороны и анимируются дальше в этом направлении.54:Летающая позитивная анимация103:Показывает летающие числа при увеличении ресурса стека.10:Шрифт25:Размер шрифта75:Изменяет размер значений ресурсов стека.103:Выбирает шрифт, используемый значениями ресурсов стека.29:Высота здоровья79:Устанавливает высоту шкалы здоровья стека.23:Высота магии73:Устанавливает высоту шкалы магии стека.128:Заполняет полосы стека справа налево и меняет местами метки значений.37:Высота выносливости87:Устанавливает высоту шкалы выносливости стека.25:Ширина полосы62:Устанавливает ширину полос стека.28:Цвет запаса сил68:Задает цвет полосы запаса сил игрока.35:выносливость-магия29:Переходная тень224:Показывает исчезающую тень потерь при уменьшении полосы. Применяется только в том случае, если включены плавные переходы.21:Цвет травмы151:Задает цвет недоступного здоровья, показанного травмой на полосе здоровья игрока.90:Устанавливает интенсивность вертикальных полос.92:Устанавливает непрозрачность вертикальных полос.27:Размер границы95:Устанавливает толщину границы вертикальной полосы.44:Шрифт летающей анимации55:Размер шрифта анимации полета83:Изменяет размер вертикальных летающих чисел.115:Выбирает шрифт, используемый вертикальными летающими числами.54:Летающая негативная анимация122:Показывает летающие числа, когда вертикальный ресурс уменьшается.37:Летающая ориентация54:Летающая позитивная анимация119:Показывает летающие числа при увеличении вертикального ресурса.10:Шрифт25:Размер шрифта89:Изменяет размер значений вертикального ресурса.117:Выбирает шрифт, используемый значениями вертикальных ресурсов.192:Выбирает, будет ли текущее значение работоспособности вертикали отображаться в виде числа или процента.271:Выбирает, будут ли цифры вертикального полета здоровья начинаться за пределами левой или правой стороны и анимироваться дальше в этом направлении.29:Высота здоровья93:Устанавливает высоту вертикальной шкалы здоровья.173:Заполняет вертикальную полосу работоспособности сверху вниз и меняет местами метки значений.29:Ширина здоровья95:Устанавливает ширину вертикальной полосы здоровья.64:Горизонтальное положение здоровья107:Перемещает вертикальную полосу здоровья влево или вправо.60:Вертикальное положение здоровья103:Перемещает вертикальную полосу здоровья вверх или вниз.174:Выбирает, будет ли текущее значение вертикальной магии отображаться в виде числа или процента.277:Выбирает, будут ли вертикальные магические летающие числа начинаться за пределами левой или правой стороны и анимироваться дальше в этом направлении.23:Высота магии87:Устанавливает высоту вертикальной шкалы магии.149:Заполняет вертикальную полосу магии сверху вниз и меняет местами метки значений.23:Ширина магии87:Устанавливает ширину вертикальной шкалы магии.62:Магика горизонтального положения101:Перемещает вертикальную полосу магии влево или вправо.56:Магика вертикальное положение97:Перемещает вертикальную полосу магии вверх или вниз.43:Вертикальное положение103:Перемещает пользовательский кадр игрока вверх или вниз.188:Выбирает, будет ли текущее значение вертикальной выносливости отображаться в виде числа или процента.264:Выбирает, будут ли цифры вертикальной выносливости начинаться за пределами левой или правой стороны и анимироваться дальше в этом направлении.37:Высота выносливости101:Устанавливает высоту вертикальной шкалы выносливости.163:Заполняет вертикальную полосу выносливости сверху вниз и меняет местами метки значений.37:Ширина выносливости101:Устанавливает ширину вертикальной шкалы выносливости.75:Выносливость в горизонтальном положении113:Перемещает вертикальную шкалу выносливости влево или вправо.71:Выносливость в вертикальном положении109:Перемещает вертикальную шкалу выносливости вверх или вниз.12:Хорошо12:тоньше12:лучший32:Позиционирование447:Регулирует, насколько точно ползунки положения NQOL перемещают элементы пользовательского интерфейса. «Обычный» перемещается по 1 за раз, «Точный» перемещается по 0,5 за раз, «Тонкий» перемещается по 0,25 за раз, а «Тонкий» перемещается по 0,1 за раз.20:Нормальный5:15 м3:1м5:30 м5:45 м4:5 м5:60 м10:КП <<1>>7:КП XP71:Включите хотя бы один раздел трекера XP.20:Дорога в КП32:Дорога к шестерне26:Дорога к максу20:Уровень <<1>>2:XP37:Непрозрачность фона92:Регулирует степень непрозрачности фона трекера XP.23:Панель опыта101:Показывает текущий индикатор опыта или опыта чемпиона.18:Диаграмма172:Записывает и показывает скользящую диаграмму прироста опыта в минуту независимо от таймеров.16:Включено72:Показывает счетчик опыта во время игры.24:Просветление156:Показывает оставшееся Просветление в виде ускоренного опыта, его максимум и процент.10:Шрифт25:Размер шрифта61:Изменяет размер текста трекера XP.74:Выбирает шрифт, используемый трекером XP.8:Цель156:Отслеживает опыт независимо от таймеров и показывает текущую оценку времени до цели.47:Горизонтальное положение86:Перемещает трекер XP влево или вправо по экрану.33:Оценщик прогресса236:Выбирает, какое скользящее окно опыта/минут используется для оценки времени, оставшегося до достижения активной цели прогресса.23:<<1>> опыта/мин31:Сбросить таймеры152:Очищает текущий прирост опыта за сеанс, процент опыта за минуту и историю графиков.40:Показать в настройках190:Здесь отображается индикатор опыта, чтобы можно было пре