чета.37:Непрозрачность фона108:Регулирует степень непрозрачности фона обратного отсчета.8:Цвет73:Изменяет цвет текста обратного отсчета.16:Включено141:Запускает обратный отсчет <<1>>, когда вы используете ультимейт на этой панели.35:<<1>> обратный отсчет82:Настройте окончательный обратный отсчет <<1>>.10:Шрифт25:Размер шрифта77:Изменяет размер текста обратного отсчета.104:Выбирает шрифт, используемый в тексте обратного отсчета.29:Передняя панель10:Фронт47:Горизонтальное положение88:Перемещает обратный отсчет <<1>> влево или вправо.14:Секунды148:Устанавливает определяемую пользователем продолжительность обратного отсчета.19:Форма фона75:Выбирает форму текста обратного отсчета.40:Показать в настройках196:Здесь отображается обратный отсчет <<1>>, чтобы можно было предварительно просмотреть изменения размещения.32:Суперспособность9:Ульт.43:Вертикальное положение84:Перемещает обратный отсчет <<1>> вверх или вниз.66:Автополучение наград PvP-ветеранства433:Автоматически получает доступные награды за ранги PvP-ветеранства. После ошибки оставшиеся награды не запрашиваются повторно, пока не будет заработана новая награда, параметр не будет включён заново или интерфейс не будет перезагружен.59:Награды PvP-ветеранства получены.26:PvP-ветеранство8:Авто7:Deutsch7:English8:Español9:Français9:日本語14:Русский12:简体中文8:Язык177:Выбирает язык NQOL. Авто использует язык игры. Новый выбор применяется после выхода из настроек NQOL.88:Перезагрузите пользовательский интерфейс игры.45:Перезагрузить интерфейс43:Советы по активному бою27:Активный квест18:Древности10:Арены45:Автоматическая привязка43:Автоматическая зарядка51:Автоматическое приглашение64:Текст автоматического приглашения20:Авторемонт60:Обратный отсчет на задней панели35:Базовые подземелья25:Баффы/дебаффы61:Объявление на центральном экране6:Чат24:Классический46:Очистить сохраненную еду43:Выбор цвета недоступен.6:Бой23:Боевая сетка35:Сопутствующий кадр43:Пользовательские рамки34:Кадры по умолчанию45:Дополнения «Подземелья»14:Рыбалка33:Рыболовный трекер12:Друзья64:Обратный отсчет на передней панели16:Шестерня12:Золото27:Групповой кадр22:Группировка25:Цвета гильдии33:Бесконечный архив25:Журнал добычи9:Луа GC10:Карта18:Миникарта12:Разное12:Маунты23:Рамка плеера38:Информация об игроке46:Взаимодействие с игроком16:Прогресс22:обеспечение16:Пирамида20:Радиальный22:Напоминания18:Сохранить20:Социальные39:Одиночные подземелья8:Стек16:Субтитры41:Синергия подсказывает10:Тикер14:Таймеры14:Трекеры31:Таймер испытания18:Испытания51:пользовательский интерфейс56:Окончательный обратный отсчет14:Утилита24:Вертикальный2:XP16:Действия14:Отметки21:Внешний вид29:Планировка бара10:Баффы10:Цвета14:Дебаффы12:Записи8:Поля14:Фильтры33:Летающая анимация10:Рамка37:Глобальные варианты16:Здоровье10:Макет12:Магика27:Офицерский чат39:Позиция и внешний вид14:Позиция26:Предустановка53:Предустановленные настройки25:Публичный чат22:Напоминания12:Строки8:Тень12:Размер14:Укладка24:Выносливость49:Отслеживание и внешний вид16:Переходы20:Типография16:Ценности18:Видимость67:Путеводитель по дорожному святилищу14:Масштаб43:Советы по активному бою27:Активный квест18:Древности10:Арены45:Автоматическая привязка51:Автоматическое приглашение35:Базовые подземелья25:Баффы/дебаффы61:Объявление на центральном экране6:Чат186:Выберите, какая учетная запись, персонаж и значения производительности будут отображаться на экране.134:Выберите, какие названия баффов и дебаффов разрешено показывать трекеру.24:Классический6:Бой23:Боевая сетка35:Сопутствующий кадр279:Настройте пользовательскую информационную панель игрока с идентификатором игрока, персонажем, чемпионскими очками, названием класса и значком класса.80:Настройте дополнения к журналу добычи игры.102:Настройте чат, друзей в сети и мониторинг поиска группы.106:Настройте боевые таймеры, параметры прицела и интеграции.76:Настройте специальные дисплеи прогресса.134:Настройте оповещения о рыбалке и помощников по улучшению качества жизни.144:Настройте вкладки мест назначения, Фрипорт и подтверждения дорожных святилищ.84:Настройте автоматизацию, связанную с группой.73:Настройте функции карты, мини-карты и GPS.108:Настройте замену кадров NQOL и видимость стандартных кадров.142:Настройка необязательных боевых интеграций и других дополнительных функций.91:Настройте фрейм состояния сопутствующего товара.84:Настройте структуру состояния группы и рейда.126:Настройте здоровье, магию, выносливость и рамку выносливости игрока.63:Настройте трекер типа редкой рыбы.134:Настройте определяемые пользователем обратные отсчеты для каждого бара.162:Управляйте взаимодействиями верхом и напоминаниями о тренировке навыков верховой езды.43:Пользовательские рамки156:Настраивайте временные метки чата, историю, расположение окон, внешний вид и фильтры.89:Настройте цвет и форму центральной боевой сетки.34:Кадры по умолчанию113:Отображение родной карты мира в виде мини-карты во время игры.45:Дополнения «Подземелья»176:Активный фильтр позволяет сосредоточиться на древностях, до сих пор не обнаруженных в кодексах.14:Рыбалка33:Рыболовный трекер16:Шестерня27:Групповой кадр22:Группировка33:Бесконечный архив161:Приглашайте игроков автоматически, когда они отправляют настроенный точный текст чата.116:Отобразите прогресс на арене на специальном дисплее прогресса.131:Отобразите прогресс в подземельях базовой игры на специальном дисплее.130:Отобразите прогресс в подземельях DLC на специальном дисплее прогресса.197:Перечислите прогресс в достижениях Infinite Archive и самые высокие зарегистрированные забеги в одиночку и в паре.123:Отображайте ход судебного разбирательства на специальном дисплее.25:Журнал добычи9:Луа GC151:Управляйте небольшими инструментами автоматизации и удобства для всего аккаунта.10:Карта18:Миникарта12:Разное12:Маунты173:Перемещайте активные боевые подсказки и просматривайте их положение во время редактирования.174:Перемещайте объявления в центре экрана и просматривайте их положение во время редактирования.190:Перемещайте подсказки о взаимодействии игроков и просматривайте их положение во время редактирования.141:Перемещайте субтитры и просматривайте их положение во время редактирования.160:Перемещайте подсказки синергии и просматривайте их положение во время редактирования.169:Переместите выделенный трекер квестов и просмотрите его положение во время редактирования.217:Переместите стандартные рамки пользовательского интерфейса игры и просмотрите их положение во время редактирования.167:Переместите рамку «Бесконечный архив» и просмотрите ее положение во время редактирования.23:Рамка плеера38:Информация об игроке46:Взаимодействие с игроком16:Прогресс22:обеспечение16:Пирамида20:Радиальный191:Перезаряжайте оружие, ремонтируйте изношенное снаряжение и автоматически связывайте новое снаряжение.116:Обновите предпочитаемую еду или напиток для каждого персонажа.20:Социальные39:Одиночные подземелья144:Просматривайте прогресс достижений одиночных подземелий на отдельном экране.8:Стек16:Субтитры41:Синергия подсказывает10:Тикер195:Отслеживайте активные основные и второстепенные положительные и отрицательные эффекты вашего персонажа.185:Отслеживайте текущий прогресс в получении опыта, недавний прирост опыта и количество опыта в минуту.183:Отслеживайте личные рекорды Infinite Archive в одиночку и в паре, а также настраивайте журналы мониторинга.14:Трекеры31:Таймер испытания183:Отслеживает прошедшее время, оставшуюся живучесть, текущий счёт и личный рекорд во время испытаний.18:Испытания159:Настройте рамки интерфейса, камеру, оповещения, трекеры и другое поведение интерфейса.51:пользовательский интерфейс56:Окончательный обратный отсчет14:Утилита24:Вертикальный2:XP153:Выбирает, являются ли текущие значения радиальных ресурсов числами или процентами.85:Изменяет размер значений радиальных ресурсов.113:Выбирает шрифт, используемый радиальными значениями ресурса.97:Устанавливает интенсивность цвета радиальных полос.88:Устанавливает непрозрачность радиальных полос.10:Шкала102:Изменяет размер всего кадра радиального проигрывателя.12:Золото152:Отслеживайте текущее зо